            { title: "Reporting the News", lines:[ { speaker: "Albert", text: "Have you seen the news? It ___ international trade hit a record high.", options: ["is reported that", "claims that", "is suggested that"], a: "is reported that" }, { speaker: "Celine", text: "Really? I thought the pandemic ___ it negatively.", options:["affects", "had affected", "has affected"], a: "had affected" }, { speaker: "Albert", text: "Well, the reporter ___ that companies had increased their interconnectedness.", options:["explained", "asked", "replied"], a: "explained" }, { speaker: "Celine", text: "That’s impressive. ___ trade continues to grow, the global economy will stabilize.", options: ["If", "Unless", "So that"], a: "If" }, { speaker: "Albert", text: "He also added that we ___ better regulations then.", options: ["need", "needed", "will need"], a: "needed" } ] },
            { title: "Privacy Settings", lines:[ { speaker: "Celine", text: "I'm worried about my data. I ___ the technician how to improve my privacy.", options: ["asked", "suggested", "told"], a: "asked" }, { speaker: "Albert", text: "He ___ that you should use a strong password.", options: ["replied", "asked", "said us"], a: "replied" }, { speaker: "Celine", text: "He also ___ me that some apps tracked our location without permission.", options:["warned", "admitted", "claimed"], a: "warned" }, { speaker: "Albert", text: "I will update my settings ___ I can stay safe.", options: ["so that", "unless", "in order to"], a: "so that" }, { speaker: "Celine", text: "Good. We won't be safe ___ we check our permissions regularly.", options: ["if", "unless", "as long as"], a: "unless" } ] },
            { title: "Information Overload", lines:[ { speaker: "Albert", text: "My teacher ___ that information overload was a serious issue.", options: ["told us", "said us", "asked us"], a: "told us" }, { speaker: "Celine", text: "I agree. I feel overwhelmed ___ I check my feed.", options: ["whenever", "unless", "in order to"], a: "whenever" }, { speaker: "Albert", text: "She ___ that we should turn off notifications at night.", options:["suggested", "claimed", "denied"], a: "suggested" }, { speaker: "Celine", text: "Did she say ___ technology caused isolation?", options: ["why", "if", "whether"], a: "why" }, { speaker: "Albert", text: "Yes, she ___ that digital interaction was replacing real-world connections.", options:["explained", "replied", "asked"], a: "explained" } ] },
            { title: "The Future of Work", lines:[ { speaker: "Celine", text: "The expert ___ that remote work would become the new standard.", options: ["claimed", "asked", "told"], a: "claimed" }, { speaker: "Albert", text: "I ___ it would affect everyone equally.", options:["asked if", "told that", "replied whether"], a: "asked if" }, { speaker: "Celine", text: "He said it ___ because of the digital divide.", options: ["won't", "wouldn't", "doesn't"], a: "wouldn't" }, { speaker: "Albert", text: "We must invest in technology ___ everyone has the same opportunities.", options: ["in order to", "unless", "so that"], a: "in order to" }, { speaker: "Celine", text: "___ we ignore this gap, inequality will keep growing.", options:["As long as", "Unless", "If"], a: "If" } ] },
            { title: "Dealing with Fake News", lines:[ { speaker: "Albert", text: "Celine, you ___ check that headline. It looks fake.", options: ["had better", "wouldn't rather", "needn't"], a: "had better" }, { speaker: "Celine", text: "You're right. It ___ that misinformation spreads faster than truth.", options: ["is believed", "is reported", "is asked"], a: "is believed" }, { speaker: "Albert", text: "I ___ I could find reliable sources.", options:["asked the librarian where", "told the librarian that", "said the librarian if"], a: "asked the librarian where" }, { speaker: "Celine", text: "She ___ that verified websites were the best.", options: ["explained", "replied", "asked"], a: "explained" }, { speaker: "Albert", text: "We should be careful ___ we don't share lies.", options: ["so that", "in order to", "unless"], a: "so that" } ] },
            { title: "Global Cooperation", lines:[ { speaker: "Celine", text: "___ we work together, we can solve global challenges.", options: ["If", "Unless", "So that"], a: "If" }, { speaker: "Albert", text: "The expert ___ that international cooperation was vital.", options:["said", "told", "asked"], a: "said" }, { speaker: "Celine", text: "I ___ we could start.", options: ["asked him how", "told him why", "replied him that"], a: "asked him how" }, { speaker: "Albert", text: "He ___ that we should focus on communication first.", options: ["replied", "warned", "admitted"], a: "replied" }, { speaker: "Celine", text: "I think he ___ right about our interconnectedness.", options:["is", "was", "had been"], a: "was" } ] },
            { title: "The Impact of AI", lines:[ { speaker: "Albert", text: "The article ___ that AI would change everything.", options:["claimed", "asked", "told"], a: "claimed" }, { speaker: "Celine", text: "I ___ if it would take our jobs.", options: ["asked", "said", "replied"], a: "asked" }, { speaker: "Albert", text: "The expert ___ that we needed to learn new skills.", options:["replied", "warned", "asked"], a: "warned" }, { speaker: "Celine", text: "We must adapt ___ stay relevant.", options: ["in order to", "unless", "as long as"], a: "in order to" }, { speaker: "Albert", text: "Yes, AI is a tool ___ we use it correctly.", options: ["as long as", "unless", "so that"], a: "as long as" } ] },
            { title: "E-waste Awareness", lines:[ { speaker: "Celine", text: "My teacher ___ us about e-waste today.", options: ["asked", "told", "said"], a: "told" }, { speaker: "Albert", text: "What did she ___?", options:["say", "tell", "ask"], a: "say" }, { speaker: "Celine", text: "She ___ that old devices polluted the environment.", options: ["explained", "asked", "suggested"], a: "explained" }, { speaker: "Albert", text: "We should recycle them ___ we reduce pollution.", options: ["so that", "unless", "in order to"], a: "so that" }, { speaker: "Celine", text: "She also ___ us to bring our old phones to school.", options:["asked", "told", "said"], a: "told" } ] }
